def backfill_caretaker_owner(apps, schema_editor):
    """Give every legacy caretaker the owner of the unit they lived in."""
    caretaker_model = apps.get_model("properties", "CareTaker")
    unit_model = apps.get_model("properties", "Unit")
    for caretaker in caretaker_model.objects.filter(owner__isnull=True).iterator():
        unit = unit_model.objects.filter(pk=caretaker.unit_id).first()
        if unit is None:
            continue
        caretaker.owner_id = unit.owner_id
        caretaker.save(update_fields=["owner"])


def create_legacy_assignments(apps, schema_editor):
    """Turn the legacy home unit of a caretaker into an assignment."""
    caretaker_model = apps.get_model("properties", "CareTaker")
    assignment_model = apps.get_model("properties", "CareTakerAssignment")
    for caretaker in caretaker_model.objects.filter(unit__isnull=False).iterator():
        assignment_model.objects.get_or_create(
            caretaker_id=caretaker.pk,
            unit_id=caretaker.unit_id,
            defaults={"is_active": True},
        )


def drop_legacy_assignments(apps, schema_editor):
    """Remove the assignments created for the legacy data."""
    assignment_model = apps.get_model("properties", "CareTakerAssignment")
    assignment_model.objects.filter(building__isnull=True).delete()


